<div class="faq-list" data-search-items>
<?php $__currentLoopData = $faqs; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $faq): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><details class="faq-item" data-search-item data-category="<?php echo e($faq['topic']); ?>"><summary><span><?php if($showTopics ?? false): ?><small><?php echo e($faq['topic']); ?></small><?php endif; ?><?php echo e($faq['question']); ?></span><span class="faq-plus" aria-hidden="true">+</span></summary><div class="faq-answer"><p><?php echo e($faq['answer']); ?></p><?php if(!empty($faq['steps'])): ?><ol style="padding-left:1.4rem;list-style:decimal"><?php $__currentLoopData = $faq['steps']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $step): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><li style="margin-top:.75rem"><?php echo e($step); ?></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></ol><?php endif; ?>
<?php if(!empty($faq['links'])): ?><div style="display:flex;flex-wrap:wrap;gap:1rem;margin-top:1rem"><?php $__currentLoopData = $faq['links']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $link): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><a class="text-link" href="<?php echo e(route($link['route'],$link['params']??[])); ?>"><?php echo e($link['label']); ?> ↗</a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php endif; ?></div></details><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
</div>
